    <div className={`min-h-screen bg-gray-50 font-sans transition-opacity duration-500 flex flex-col ${mounted ? 'opacity-100' : 'opacity-0'}`}>

      {/* Background Particles - Fixed */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <ParticleBackground />
      </div>

      {/* Top Navbar */}
      <Header toggleSidebar={toggleSidebar} />

      {/* Main Layout Container */}
      <div className="flex flex-1 relative z-10 max-w-[1920px] mx-auto w-full">

        {/* Sidebar - Hidden on mobile, controlled by state on desktop */}
        <div className="hidden lg:block h-[calc(100vh-73px)] sticky top-[73px]">
           <Sidebar 
             collapsed={isSidebarCollapsed} 
             activePage={currentPage} 
             onNavigate={setCurrentPage} 
           />
        </div>

        {/* Main Content Area */}
        <main className={`flex-1 p-4 md:p-8 overflow-y-auto h-[calc(100vh-73px)] scroll-smooth`}>
          <div className="max-w-7xl mx-auto animate-slide-right">
            {renderPage()}
          </div>
        </main>

      </div>
    </div>
  );
};

