                      )}

                      {/* Meta */}
                      <div className={`flex items-center justify-end space-x-1 mt-1 text-[10px] ${isMe ? 'text-blue-100' : 'text-gray-400'}`}>
                        <span>{msg.timestamp}</span>
                        {isMe && (
