                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-3 md:p-4 bg-gray-50 border-t border-gray-200 flex items-end space-x-2">
               <button className="p-2 text-gray-500 hover:bg-gray-200 rounded-full transition-colors mb-1">
                 <Smile className="w-6 h-6" />
               </button>
               <button 
                 onClick={handleSendFile}
                 className="p-2 text-gray-500 hover:bg-gray-200 rounded-full transition-colors mb-1" 
                 title="Attach File"
               >
                 <Paperclip className="w-6 h-6" />
               </button>

               <div className="flex-1 bg-white border border-gray-200 rounded-2xl px-4 py-3 shadow-sm focus-within:ring-2 focus-within:ring-blue-100 focus-within:border-blue-300 transition-all">
                 <input 
                   type="text" 
                   value={inputText}
                   onChange={(e) => setInputText(e.target.value)}
                   onKeyDown={handleKeyPress}
                   placeholder="Type a message..." 
                   className="w-full bg-transparent border-none focus:outline-none text-gray-800 placeholder-gray-400 max-h-32"
                 />
               </div>

               {inputText.trim() ? (
                 <button 
                   onClick={handleSendMessage}
                   className="p-3 bg-blue-600 text-white rounded-full hover:bg-blue-700 shadow-md transition-transform transform active:scale-95 mb-1"
                 >
                   <Send className="w-5 h-5" />
                 </button>
               ) : (
                 <button className="p-3 bg-blue-600 text-white rounded-full hover:bg-blue-700 shadow-md transition-transform transform active:scale-95 mb-1">
                   <Mic className="w-5 h-5" />
                 </button>
               )}
            </div>
          </>
        ) : (
          /* Empty State for Desktop */
          <div className="hidden md:flex flex-1 flex-col items-center justify-center bg-gray-50 border-l border-gray-200 text-center p-8">
             <div className="w-40 h-40 bg-gray-100 rounded-full flex items-center justify-center mb-6 animate-pulse-custom">
               <img src="https://cdni.iconscout.com/illustration/premium/thumb/online-community-5633453-4694464.png" alt="Community" className="w-28 opacity-60" />
             </div>
             <h2 className="text-2xl font-bold text-gray-800 mb-2">EduDash Communities</h2>
             <p className="text-gray-500 max-w-md">Select a group or friend from the sidebar to start chatting. Collaborate, share files, and study together.</p>
             <div className="mt-8 flex items-center space-x-2 text-xs text-gray-400">
               <div className="w-2 h-2 bg-green-500 rounded-full"></div>
               <span>End-to-end encrypted for study integrity</span>
             </div>
          </div>
        )}
      </div>

    </div>
