      case 'success': return <CheckCircle className="w-6 h-6 text-green-500" />;
      default: return <Info className="w-6 h-6 text-blue-500" />;
    }
  };

  const getBgColor = (type: string) => {
     switch(type) {
      case 'alert': return 'bg-red-50';
      case 'success': return 'bg-green-50';
      default: return 'bg-blue-50';
    }
  };

  return (
    <div className="animate-fade-up max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-2xl font-bold text-gray-800">Notifications</h2>
        <button className="text-sm text-blue-600 font-medium hover:bg-blue-50 px-3 py-1.5 rounded-lg transition-colors flex items-center">
          <Check className="w-4 h-4 mr-1" /> Mark all as read
        </button>
      </div>

      <div className="bg-white rounded-3xl shadow-sm overflow-hidden">
        {NOTIFICATIONS.length > 0 ? (
          <div className="divide-y divide-gray-100">
             {NOTIFICATIONS.map((notif) => (
                <div 
                  key={notif.id} 
                  className={`p-6 flex items-start hover:bg-gray-50 transition-colors cursor-pointer ${notif.read ? 'opacity-70' : ''}`}
                >
                   <div className={`p-3 rounded-full mr-4 flex-shrink-0 ${getBgColor(notif.type)}`}>
