import ProfilePage from './components/ProfilePage';

const App: React.FC = () => {
  const [mounted, setMounted] = useState(false);
  const [currentPage, setCurrentPage] = useState('Home');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const toggleSidebar = () => {
    // On mobile, this opens/closes the drawer. On desktop, it collapses.
    if (window.innerWidth < 1024) {
      setIsMobileMenuOpen(!isMobileMenuOpen);
    } else {
      setIsSidebarCollapsed(!isSidebarCollapsed);
    }
  };

  const handleNavigate = (page: string) => {
    setCurrentPage(page);
    setIsMobileMenuOpen(false); // Auto-close drawer on navigation
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'Home': return <Home onNavigate={handleNavigate} />;
      case 'My Notes': return <MyNotes />;
      case 'Tests & Quizzes': return <TestsQuizzes />;
      case 'Communities': return <Communities />;
      case 'AI Tutor': return <AITutor />;
      case 'Progress': return <ProgressPage />;
      case 'Settings': return <Settings />;
      case 'Notifications': return <NotificationsPage />;
      case 'Profile': return <ProfilePage />;
      default: return <Home onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className={`min-h-screen bg-gray-50 font-sans transition-opacity duration-500 flex flex-col ${mounted ? 'opacity-100' : 'opacity-0'}`}>

      {/* Background Particles - Fixed */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <ParticleBackground />
      </div>

      {/* Top Navbar */}
      <Header toggleSidebar={toggleSidebar} onNavigate={handleNavigate} />

      {/* Main Layout Container */}
      <div className="flex flex-1 relative z-10 max-w-[1920px] mx-auto w-full">

        {/* Mobile Sidebar Overlay */}
        {isMobileMenuOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-40 lg:hidden transition-opacity" 
            onClick={() => setIsMobileMenuOpen(false)}
          />
        )}

        {/* Sidebar */}
        <div className={`
          fixed lg:sticky top-[73px] z-50 h-[calc(100vh-73px)] transition-transform duration-300
          ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
          lg:block
        `}>
           <Sidebar 
             collapsed={isSidebarCollapsed} 
             activePage={currentPage} 
             onNavigate={handleNavigate} 
           />
        </div>

        {/* Main Content Area */}
        <main className={`flex-1 p-3 md:p-6 lg:p-8 overflow-y-auto h-[calc(100vh-73px)] scroll-smooth`}>
          <div className="max-w-7xl mx-auto animate-slide-right">
            {renderPage()}
          </div>
        </main>

      </div>
    </div>
  );
};

export default App;

