const Communities: React.FC = () => {
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [chats, setChats] = useState<Chat[]>(MOCK_CHATS);
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const activeChat = chats.find(c => c.id === activeChatId);
  const filteredChats = chats.filter(c => c.name.toLowerCase().includes(searchQuery.toLowerCase()));

  useEffect(() => {
    scrollToBottom();
  }, [activeChat?.messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = () => {
    if ((!inputText.trim()) || !activeChatId) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      senderId: CURRENT_USER_ID,
      text: inputText,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'sent'
    };

    updateChatMessages(activeChatId, newMessage);
    setInputText('');
  };

  const handleSendFile = () => {
    if (!activeChatId) return;

    // Simulate sending a file
    const newMessage: Message = {
      id: Date.now().toString(),
      senderId: CURRENT_USER_ID,
      file: {
        name: `Notes_${new Date().toLocaleDateString().replace(/\//g, '-')}.pdf`,
        type: 'file',
        size: '1.5 MB'
      },
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'sent'
    };
    updateChatMessages(activeChatId, newMessage);
  };

  const updateChatMessages = (chatId: string, message: Message) => {
    setChats(prevChats => prevChats.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: [...chat.messages, message],
          lastMessage: message.file ? 'Sent a file' : (message.text || ''),
          lastMessageTime: 'Just now'
        };
      }
      return chat;
    }));
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSendMessage();
  };

  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] bg-white rounded-3xl shadow-sm overflow-hidden flex border border-gray-200">

      {/* LEFT SIDEBAR: Chat List */}
      <div className={`${activeChatId ? 'hidden md:flex' : 'flex'} w-full md:w-80 lg:w-96 flex-col border-r border-gray-200 bg-white`}>

        {/* Header */}
        <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center sticky top-0 z-10">
           <h2 className="text-xl font-bold text-gray-800">Communities</h2>
           <div className="flex space-x-2">
             <button className="p-2 text-gray-600 hover:bg-gray-200 rounded-full transition-colors">
               <Plus className="w-5 h-5" />
             </button>
             <button className="p-2 text-gray-600 hover:bg-gray-200 rounded-full transition-colors">
               <MoreVertical className="w-5 h-5" />
             </button>
           </div>
        </div>

        {/* Search */}
        <div className="p-3 border-b border-gray-100">
          <div className="relative">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
             <input 
               type="text" 
               placeholder="Search chats" 
               className="w-full bg-gray-100 text-gray-800 text-sm rounded-xl pl-9 pr-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-100"
               value={searchQuery}
               onChange={(e) => setSearchQuery(e.target.value)}
             />
          </div>
        </div>

        {/* List */}
        <div className="flex-1 overflow-y-auto">
           {filteredChats.map(chat => (
             <div 
               key={chat.id}
               onClick={() => setActiveChatId(chat.id)}
               className={`flex items-center p-4 cursor-pointer hover:bg-gray-50 transition-colors border-b border-gray-50 ${activeChatId === chat.id ? 'bg-blue-50 hover:bg-blue-50' : ''}`}
             >
               <img src={chat.avatar} alt={chat.name} className="w-12 h-12 rounded-full object-cover border border-gray-200 flex-shrink-0" />
               <div className="ml-3 flex-1 overflow-hidden">
                 <div className="flex justify-between items-baseline mb-1">
                    <h3 className="text-sm font-semibold text-gray-900 truncate">{chat.name}</h3>
                    <span className={`text-[10px] ${chat.unreadCount > 0 ? 'text-green-500 font-bold' : 'text-gray-400'}`}>{chat.lastMessageTime}</span>
                 </div>
                 <div className="flex justify-between items-center">
                    <p className="text-sm text-gray-500 truncate flex-1">{chat.lastMessage}</p>
                    {chat.unreadCount > 0 && (
                      <span className="ml-2 bg-green-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center">
                        {chat.unreadCount}
                      </span>
                    )}
                 </div>
               </div>
             </div>
           ))}
        </div>
      </div>

      {/* RIGHT MAIN: Conversation Area */}
      <div className={`${!activeChatId ? 'hidden md:flex' : 'flex'} flex-1 flex-col bg-white`}>
        {activeChat ? (
          <>
            {/* Chat Header */}
            <div className="p-3 md:p-4 bg-gray-50 border-b border-gray-200 flex justify-between items-center shadow-sm z-10">
               <div className="flex items-center">
                 <button onClick={() => setActiveChatId(null)} className="md:hidden mr-2 p-1 text-gray-600">
                    <ArrowLeft className="w-6 h-6" />
                 </button>
                 <img src={activeChat.avatar} alt={activeChat.name} className="w-10 h-10 rounded-full border border-gray-200" />
                 <div className="ml-3">
                    <h3 className="text-gray-800 font-bold text-sm md:text-base">{activeChat.name}</h3>
                    <p className="text-[10px] text-gray-500">
                      {activeChat.type === 'group' ? activeChat.members : 'Online'}
                    </p>
                 </div>
               </div>
               <div className="flex items-center space-x-2 text-gray-600">
                  <button className="p-2 hover:bg-gray-200 rounded-full transition-colors"><Search className="w-5 h-5" /></button>
                  <button className="p-2 hover:bg-gray-200 rounded-full transition-colors"><MoreVertical className="w-5 h-5" /></button>
               </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-4 bg-gray-50" style={{ backgroundImage: 'radial-gradient(#cbd5e1 0.5px, transparent 0.5px)', backgroundSize: '15px 15px' }}>
              {activeChat.messages.map((msg, idx) => {
                const isMe = msg.senderId === CURRENT_USER_ID;
                return (
                  <div key={`${msg.id}-${idx}`} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                    <div className={`relative max-w-[85%] md:max-w-[70%] rounded-2xl p-3 shadow-sm ${
                      isMe 
                        ? 'bg-blue-600 text-white rounded-tr-none' 
                        : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                    }`}>
                      {msg.text && <p className="text-sm md:text-base leading-relaxed">{msg.text}</p>}
                      {msg.file && (
                        <div className={`flex items-center p-3 rounded-xl mt-1 space-x-3 cursor-pointer ${isMe ? 'bg-blue-700' : 'bg-gray-100'}`}>
                           <div className="p-2 bg-white/20 rounded-lg">
                             <FileText className={`w-5 h-5 ${isMe ? 'text-white' : 'text-red-500'}`} />
                           </div>
                           <div className="overflow-hidden">
                              <p className={`text-xs font-semibold truncate ${isMe ? 'text-white' : 'text-gray-800'}`}>{msg.file.name}</p>
                              <p className={`text-[10px] ${isMe ? 'text-blue-200' : 'text-gray-500'}`}>{msg.file.size}</p>
                           </div>
                        </div>
                      )}
                      <div className={`flex items-center justify-end space-x-1 mt-1 text-[9px] ${isMe ? 'text-blue-100' : 'text-gray-400'}`}>
                        <span>{msg.timestamp}</span>
                        {isMe && (msg.status === 'read' ? <CheckCheck className="w-3 h-3" /> : <Check className="w-3 h-3" />)}
                      </div>
                    </div>
                  </div>
                );
              })}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-3 md:p-4 bg-gray-50 border-t border-gray-200 flex items-end space-x-2">
               <button className="p-2 text-gray-500 hover:bg-gray-200 rounded-full transition-colors mb-1">
                 <Smile className="w-6 h-6" />
               </button>
               <button onClick={handleSendFile} className="p-2 text-gray-500 hover:bg-gray-200 rounded-full transition-colors mb-1">
                 <Paperclip className="w-6 h-6" />
               </button>
               <div className="flex-1 bg-white border border-gray-200 rounded-2xl px-4 py-3 shadow-sm focus-within:ring-2 focus-within:ring-blue-100 transition-all">
                 <input 
                   type="text" 
                   value={inputText}
                   onChange={(e) => setInputText(e.target.value)}
                   onKeyDown={handleKeyPress}
                   placeholder="Type a message..." 
                   className="w-full bg-transparent border-none focus:outline-none text-sm text-gray-800"
                 />
               </div>
               <button onClick={handleSendMessage} className="p-3 bg-blue-600 text-white rounded-full hover:bg-blue-700 shadow-md transition-all active:scale-95 mb-1">
                 {inputText.trim() ? <Send className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
               </button>
            </div>
          </>
        ) : (
          <div className="hidden md:flex flex-1 flex-col items-center justify-center bg-gray-50 text-center p-8">
             <div className="w-32 h-32 bg-gray-100 rounded-full flex items-center justify-center mb-6">
               <Users className="w-16 text-gray-300" />
             </div>
             <h2 className="text-xl font-bold text-gray-800 mb-2">Select a conversation</h2>
             <p className="text-gray-500 text-sm max-w-xs">Chat with your friends and classmates to stay ahead in your studies.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Communities;

import React, { useState } from 'react';
import { RECENT_NOTES } from '../constants';
import { Note } from '../types';
import { 
  Folder, 
  ChevronLeft, 
  Plus, 
  MoreVertical, 
  Search,
  Bold,
  Italic,
  Underline,
  List,
  AlignLeft,
  FileText
} from 'lucide-react';

const MyNotes: React.FC = () => {
  // State
  const [activeFolder, setActiveFolder] = useState<string | null>(null);
  const [notes, setNotes] = useState<Note[]>(RECENT_NOTES);
  const [activeNoteId, setActiveNoteId] = useState<number | null>(null);

  // Derived Data
  // Fix: Explicitly type Set to string to ensure correct inference of folders as string[]
  const folders = Array.from(new Set<string>(notes.map(n => n.folder))).sort();
  // Ensure we have specific subjects if not in data, or just use dynamic
  const allFolders = ['Biology', 'History', 'Math', 'Design Thinking', 'Other']; 
  // Merge dynamic and static to ensure all are present if needed, for now just use dynamic from data + defaults
  // Fix: Explicitly type Set to string to ensure uniqueFolders is string[]
  const uniqueFolders = Array.from(new Set<string>([...allFolders, ...folders]));

  const filteredNotes = activeFolder 
    ? notes.filter(n => n.folder === activeFolder) 
    : [];

  const activeNote = notes.find(n => n.id === activeNoteId);

  // Handlers
  const handleCreateNote = () => {
    if (!activeFolder) return;

    const newNote: Note = {
      id: Date.now(),
      title: 'Untitled Page',
      folder: activeFolder,
      content: '',
      color: 'gray',
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    };

    setNotes([newNote, ...notes]);
    setActiveNoteId(newNote.id);
  };

  const handleUpdateNote = (id: number, field: keyof Note, value: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, [field]: value } : n));
  };

  const getFolderColor = (folder: string) => {
    switch(folder) {
        case 'Biology': return 'bg-green-100 text-green-700';
        case 'History': return 'bg-amber-100 text-amber-700';
        case 'Math': return 'bg-purple-100 text-purple-700';
        case 'Design Thinking': return 'bg-orange-100 text-orange-700';
        default: return 'bg-gray-100 text-gray-700';
    }
  };

  // --- VIEW 1: FOLDER GRID ---
  if (!activeFolder) {
    return (
      <div className="animate-fade-up h-full flex flex-col">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-bold text-gray-800">My Notebooks</h2>
          <div className="relative">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4"/>
             <input type="text" placeholder="Search notebooks..." className="pl-10 pr-4 py-2 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-100 bg-white" />
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {uniqueFolders.map((folder, idx) => {
             const count = notes.filter(n => n.folder === folder).length;
             return (
               <div 
                 key={folder}
                 // Fix: folder is now correctly inferred as string instead of unknown
                 onClick={() => { setActiveFolder(folder); setActiveNoteId(null); }}
                 className="bg-white p-6 rounded-3xl shadow-sm hover:shadow-md transition-all cursor-pointer group flex flex-col items-center justify-center text-center aspect-square border border-transparent hover:border-blue-100"
               >
                 <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-4 transition-transform group-hover:scale-110 ${getFolderColor(folder)}`}>
                   <Folder className="w-8 h-8 fill-current opacity-80" />
                 </div>
                 <h3 className="text-lg font-bold text-gray-800 group-hover:text-blue-600 transition-colors">{folder}</h3>
                 <p className="text-sm text-gray-500 mt-1">{count} {count === 1 ? 'file' : 'files'}</p>
               </div>
             );
          })}

          {/* Add Folder Button Mock */}
          <div className="border-2 border-dashed border-gray-200 p-6 rounded-3xl flex flex-col items-center justify-center text-center aspect-square cursor-pointer hover:bg-gray-50 hover:border-gray-300 transition-all text-gray-400 hover:text-gray-600">
             <Plus className="w-10 h-10 mb-2" />
             <span className="font-medium">New Folder</span>
          </div>
        </div>
      </div>
    );
  }

  // --- VIEW 2: ONENOTE STYLE EDITOR ---
  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] flex bg-white rounded-3xl shadow-sm overflow-hidden border border-gray-200">

      {/* Sidebar: Pages List */}
      <div className="w-64 bg-gray-50 border-r border-gray-200 flex flex-col flex-shrink-0">
        {/* Header: Back & Folder Name */}
        <div className="p-4 border-b border-gray-200 flex items-center space-x-2 bg-white">
           <button onClick={() => setActiveFolder(null)} className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-500 transition-colors">
             <ChevronLeft className="w-5 h-5" />
           </button>
           <span className="font-bold text-gray-800 truncate">{activeFolder}</span>
        </div>

        {/* Notes List */}
        <div className="flex-1 overflow-y-auto">
           {filteredNotes.length === 0 ? (
             <div className="p-8 text-center text-gray-400 text-sm">No notes yet</div>
           ) : (
             <div className="divide-y divide-gray-100">
               {filteredNotes.map(note => (
                 <div 
                   key={note.id}
                   onClick={() => setActiveNoteId(note.id)}
                   className={`p-4 cursor-pointer hover:bg-white transition-colors border-l-4 ${activeNoteId === note.id ? 'bg-white border-blue-500' : 'border-transparent'}`}
                 >
                   <h4 className={`font-medium text-sm mb-1 truncate ${activeNoteId === note.id ? 'text-blue-700' : 'text-gray-700'}`}>{note.title || 'Untitled Page'}</h4>
                   <p className="text-xs text-gray-400 truncate">{note.content || 'No additional text'}</p>
                 </div>
               ))}
             </div>
           )}
        </div>

        {/* Footer: Add Page */}
        <div className="p-4 border-t border-gray-200 bg-white">
           <button 
             onClick={handleCreateNote}
             className="w-full py-2 flex items-center justify-center space-x-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-xl transition-colors font-medium text-sm"
           >
             <Plus className="w-4 h-4" />
             <span>Add Page</span>
           </button>
        </div>
      </div>

      {/* Main: Editor Area */}
      <div className="flex-1 flex flex-col bg-white">
         {activeNote ? (
           <>
             {/* Toolbar */}
             <div className="h-12 border-b border-gray-100 flex items-center px-4 space-x-1">
                <div className="flex items-center space-x-1 mr-4 border-r border-gray-200 pr-4">
                  <span className="text-xs text-gray-400 font-mono">{activeNote.date}</span>
                </div>
                {[Bold, Italic, Underline].map((Icon, i) => (
                   <button key={i} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors">
                     <Icon className="w-4 h-4" />
                   </button>
                ))}
                <div className="w-px h-4 bg-gray-200 mx-2"></div>
                {[AlignLeft, List].map((Icon, i) => (
                   <button key={i} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors">
                     <Icon className="w-4 h-4" />
                   </button>
                ))}
             </div>

             {/* Content */}
             <div className="flex-1 overflow-y-auto p-8 md:p-12">
                <input 
                  type="text" 
                  value={activeNote.title}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'title', e.target.value)}
                  placeholder="Page Title"
                  className="w-full text-4xl font-bold text-gray-800 placeholder-gray-300 border-none focus:outline-none focus:ring-0 bg-transparent mb-6"
                />

                {/* Simple Textarea for content to be robust, mimicking OneNote canvas */}
                <textarea
                  value={activeNote.content}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'content', e.target.value)}
                  placeholder="Start typing..."
                  className="w-full h-[calc(100%-80px)] resize-none text-gray-600 text-lg leading-relaxed border-none focus:outline-none focus:ring-0 bg-transparent"
                />
             </div>
           </>
         ) : (
           <div className="flex-1 flex flex-col items-center justify-center text-gray-300">
             <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center mb-4">
                <FileText className="w-10 h-10" />
             </div>
             <p className="text-lg font-medium">Select a page to edit</p>
             <p className="text-sm">or create a new one</p>
           </div>
         )}
      </div>

    </div>
  );
};

export default MyNotes;

