import React, { useState } from 'react';
import { RECENT_NOTES } from '../constants';
import { Note } from '../types';
import { 
  Folder, 
  ChevronLeft, 
  Plus, 
  MoreVertical, 
  Search,
  Bold,
  Italic,
  Underline,
  List,
  AlignLeft,
  FileText,
  Upload,
  Download,
  Share2,
  FileCheck
} from 'lucide-react';

const MyNotes: React.FC = () => {
  const [activeFolder, setActiveFolder] = useState<string | null>(null);
  const [notes, setNotes] = useState<Note[]>(RECENT_NOTES);
  const [activeNoteId, setActiveNoteId] = useState<number | null>(null);
  const [isExporting, setIsExporting] = useState(false);

  const folders = Array.from(new Set<string>(notes.map(n => n.folder))).sort();
  const allFolders = ['Biology', 'History', 'Math', 'Design Thinking', 'Other']; 
  const uniqueFolders = Array.from(new Set<string>([...allFolders, ...folders]));

  const filteredNotes = activeFolder 
    ? notes.filter(n => n.folder === activeFolder) 
    : [];

  const activeNote = notes.find(n => n.id === activeNoteId);

  const handleCreateNote = () => {
    if (!activeFolder) return;
    const newNote: Note = {
      id: Date.now(),
      title: 'New Page',
      folder: activeFolder,
      content: '',
      color: 'gray',
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    };
    setNotes([newNote, ...notes]);
    setActiveNoteId(newNote.id);
  };

  const handleUpdateNote = (id: number, field: keyof Note, value: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, [field]: value } : n));
  };

  const handleUploadPDF = () => {
    // Simulating file upload
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/pdf';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file && activeFolder) {
        const newNote: Note = {
          id: Date.now(),
          title: file.name,
          folder: activeFolder,
          content: '[PDF Content Extracted: This is a preview of the uploaded PDF file. Use the export tool to download it back.]',
          color: 'blue',
          date: 'Just now'
        };
        setNotes([newNote, ...notes]);
        setActiveNoteId(newNote.id);
      }
    };
    input.click();
  };

  const handleExportPDF = () => {
    if (!activeNote) return;
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      // Simulate download
      const element = document.createElement('a');
      const file = new Blob([activeNote.content], {type: 'text/plain'});
      element.href = URL.createObjectURL(file);
      element.download = `${activeNote.title.replace(/\s+/g, '_')}.pdf`;
      document.body.appendChild(element);
      element.click();
      document.body.removeChild(element);
    }, 1500);
  };

  const getFolderColor = (folder: string) => {
    switch(folder) {
        case 'Biology': return 'bg-green-100 text-green-700';
        case 'History': return 'bg-amber-100 text-amber-700';
        case 'Math': return 'bg-purple-100 text-purple-700';
        case 'Design Thinking': return 'bg-orange-100 text-orange-700';
        default: return 'bg-gray-100 text-gray-700';
    }
  };

  if (!activeFolder) {
    return (
      <div className="animate-fade-up h-full flex flex-col">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
          <div>
            <h2 className="text-3xl font-black text-gray-800">My Notebooks</h2>
            <p className="text-sm text-gray-500 font-medium">Manage your personal study material</p>
          </div>
          <div className="flex space-x-3 w-full sm:w-auto">
            <button 
              onClick={() => setActiveFolder('Other')}
              className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
            >
              <Plus className="w-5 h-5" />
              <span>Create Note</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
          {uniqueFolders.map((folder) => {
             const count = notes.filter(n => n.folder === folder).length;
             return (
               <div 
                 key={folder}
                 onClick={() => { setActiveFolder(folder); setActiveNoteId(null); }}
                 className="bg-white p-6 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all cursor-pointer group flex flex-col items-center justify-center text-center aspect-square border border-transparent hover:border-blue-100 relative overflow-hidden"
               >
                 <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mb-4 transition-transform group-hover:scale-110 group-hover:rotate-6 ${getFolderColor(folder)}`}>
                   <Folder className="w-10 h-10 fill-current opacity-80" />
                 </div>
                 <h3 className="text-lg font-bold text-gray-800 group-hover:text-blue-600 transition-colors truncate w-full px-2">{folder}</h3>
                 <p className="text-sm text-gray-500 mt-1 font-medium">{count} {count === 1 ? 'file' : 'files'}</p>
                 <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                    <div className="p-2 bg-gray-50 rounded-full hover:bg-gray-100">
                       <MoreVertical className="w-4 h-4 text-gray-400" />
                    </div>
                 </div>
               </div>
             );
          })}
          <div className="border-4 border-dashed border-gray-100 p-6 rounded-[2.5rem] flex flex-col items-center justify-center text-center aspect-square cursor-pointer hover:bg-white hover:border-blue-200 transition-all group">
             <div className="p-4 bg-gray-50 rounded-3xl group-hover:bg-blue-50 transition-colors">
               <Plus className="w-12 h-12 text-gray-300 group-hover:text-blue-500" />
             </div>
             <span className="font-bold text-gray-400 group-hover:text-blue-500 mt-4">Add Project</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] flex bg-white rounded-[2rem] shadow-xl overflow-hidden border border-gray-100">

      <div className="w-72 bg-gray-50 border-r border-gray-200 flex flex-col flex-shrink-0">
        <div className="p-5 border-b border-gray-200 flex items-center space-x-3 bg-white">
           <button onClick={() => setActiveFolder(null)} className="p-2 hover:bg-gray-100 rounded-xl text-gray-500 transition-all hover:scale-110">
             <ChevronLeft className="w-5 h-5" />
           </button>
           <span className="font-black text-gray-800 truncate text-lg">{activeFolder}</span>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-1">
           {filteredNotes.length === 0 ? (
             <div className="p-8 text-center text-gray-400 text-sm italic">Folder is empty</div>
           ) : (
             filteredNotes.map(note => (
               <div 
                 key={note.id}
                 onClick={() => setActiveNoteId(note.id)}
                 className={`p-4 rounded-2xl cursor-pointer transition-all ${activeNoteId === note.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'hover:bg-white text-gray-700'}`}
               >
                 <div className="flex items-center space-x-3">
                   <FileText className={`w-4 h-4 flex-shrink-0 ${activeNoteId === note.id ? 'text-indigo-100' : 'text-gray-400'}`} />
                   <h4 className="font-bold text-sm truncate">{note.title || 'Untitled Page'}</h4>
                 </div>
                 <p className={`text-[10px] mt-1 truncate ${activeNoteId === note.id ? 'text-indigo-200' : 'text-gray-400'}`}>
                    {note.date} • {note.content.substring(0, 30) || 'Empty note'}
                 </p>
               </div>
             ))
           )}
        </div>

        <div className="p-4 bg-white border-t border-gray-100 space-y-2">
           <button 
             onClick={handleUploadPDF}
             className="w-full py-3 flex items-center justify-center space-x-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-2xl transition-all font-bold text-sm border border-indigo-100"
           >
             <Upload className="w-4 h-4" />
             <span>Upload PDF</span>
           </button>
           <button 
             onClick={handleCreateNote}
             className="w-full py-3 flex items-center justify-center space-x-3 bg-gray-900 hover:bg-black text-white rounded-2xl transition-all font-bold text-sm"
           >
             <Plus className="w-4 h-4" />
             <span>New Page</span>
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white">
         {activeNote ? (
           <>
             <div className="h-16 border-b border-gray-100 flex items-center justify-between px-6">
                <div className="flex items-center space-x-1">
                  {[Bold, Italic, Underline, List, AlignLeft].map((Icon, i) => (
                    <button key={i} className="p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-800 rounded-xl transition-all">
                      <Icon className="w-4 h-4" />
                    </button>
                  ))}
                </div>
                <div className="flex items-center space-x-3">
                   <button 
                     onClick={handleExportPDF}
                     disabled={isExporting}
                     className="flex items-center space-x-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-all disabled:opacity-50"
                   >
                     {isExporting ? <div className="w-3 h-3 border-2 border-blue-600/30 border-t-blue-600 rounded-full animate-spin"></div> : <Download className="w-3.5 h-3.5" />}
                     <span>{isExporting ? 'Exporting...' : 'Export PDF'}</span>
                   </button>
                   <button className="flex items-center space-x-2 px-4 py-2 bg-green-50 text-green-600 rounded-xl font-bold text-xs hover:bg-green-100 transition-all">
                     <Share2 className="w-3.5 h-3.5" />
                     <span>Share</span>
                   </button>
                </div>
             </div>

             <div className="flex-1 overflow-y-auto p-10 md:p-16 max-w-4xl mx-auto w-full">
                <div className="flex items-center justify-between mb-8">
                   <span className="bg-gray-100 text-gray-500 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full">{activeNote.folder}</span>
                   <span className="text-[10px] text-gray-400 font-medium">Last Edited: {activeNote.date}</span>
                </div>
                <input 
                  type="text" 
                  value={activeNote.title}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'title', e.target.value)}
                  placeholder="Untitled Page"
                  className="w-full text-5xl font-black text-gray-900 placeholder-gray-100 border-none focus:outline-none focus:ring-0 bg-transparent mb-10 selection:bg-blue-100"
                />
                <textarea
                  value={activeNote.content}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'content', e.target.value)}
                  placeholder="The page is empty. Start typing your thoughts or paste research here..."
                  className="w-full h-full min-h-[500px] resize-none text-gray-700 text-xl leading-relaxed border-none focus:outline-none focus:ring-0 bg-transparent selection:bg-blue-100"
                />
             </div>
           </>
         ) : (
           <div className="flex-1 flex flex-col items-center justify-center text-gray-200">
             <div className="w-32 h-32 bg-gray-50 rounded-[2.5rem] flex items-center justify-center mb-6">
                <FileCheck className="w-16 h-16 opacity-10" />
             </div>
             <p className="text-xl font-black text-gray-400">Select a note to begin editing</p>
             <p className="text-sm font-bold text-gray-300">Your ideas deserve to be written down.</p>
           </div>
         )}
      </div>
    </div>
  );
};

export default MyNotes;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, 
  MoreVertical, 
  Paperclip, 
  Send, 
  FileText, 
  Mic,
  ArrowLeft,
  Check,
  CheckCheck,
  Smile,
  Plus,
  Users,
  Layout,
  HardDrive,
  X
} from 'lucide-react';
import { RECENT_NOTES } from '../constants';

interface Message {
  id: string;
  senderId: string;
  text?: string;
  file?: {
    name: string;
    type: 'image' | 'file';
    url?: string;
    size?: string;
  };
  timestamp: string;
  status: 'sent' | 'delivered' | 'read';
}

interface Chat {
  id: string;
  type: 'group' | 'direct';
  name: string;
  avatar: string;
  lastMessage: string;
  lastMessageTime: string;
  unreadCount: number;
  members?: string;
  status?: 'online' | 'offline' | string;
  messages: Message[];
}

const CURRENT_USER_ID = 'me';

const MOCK_CHATS: Chat[] = [
  {
    id: '1',
    type: 'group',
    name: 'AP Chem Study Group',
    avatar: 'https://ui-avatars.com/api/?name=AP+Chem&background=3b82f6&color=fff',
    lastMessage: 'Does anyone have the notes for Ch 4?',
    lastMessageTime: '10:45 AM',
    unreadCount: 3,
    members: 'Alice, Bob, Charlie, You',
    messages: [
      { id: 'm1', senderId: 'u1', text: 'Hey guys, when is the quiz?', timestamp: '10:30 AM', status: 'read' },
      { id: 'm2', senderId: 'me', text: 'I think it is next Tuesday.', timestamp: '10:32 AM', status: 'read' },
      { id: 'm3', senderId: 'u2', text: 'Does anyone have the notes for Ch 4?', timestamp: '10:45 AM', status: 'read' },
    ]
  },
  {
    id: '2',
    type: 'direct',
    name: 'Sarah Jenkins',
    avatar: 'https://ui-avatars.com/api/?name=Sarah+Jenkins&background=ec4899&color=fff',
    lastMessage: 'Thanks for the help!',
    lastMessageTime: 'Yesterday',
    unreadCount: 0,
    status: 'online',
    messages: [
      { id: 'm1', senderId: 'me', text: 'Here is the file you asked for.', file: { name: 'Lab_Report_Final.pdf', type: 'file', size: '2.4 MB' }, timestamp: 'Yesterday', status: 'read' },
      { id: 'm2', senderId: 'u3', text: 'Thanks for the help!', timestamp: 'Yesterday', status: 'read' },
    ]
  }
];

const Communities: React.FC = () => {
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [chats, setChats] = useState<Chat[]>(MOCK_CHATS);
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [showAttachMenu, setShowAttachMenu] = useState(false);
  const [showNotesPicker, setShowNotesPicker] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const attachMenuRef = useRef<HTMLDivElement>(null);

  const activeChat = chats.find(c => c.id === activeChatId);
  const filteredChats = chats.filter(c => c.name.toLowerCase().includes(searchQuery.toLowerCase()));

  useEffect(() => {
    scrollToBottom();
  }, [activeChat?.messages]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (attachMenuRef.current && !attachMenuRef.current.contains(event.target as Node)) {
        setShowAttachMenu(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = () => {
    if ((!inputText.trim()) || !activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      senderId: CURRENT_USER_ID,
      text: inputText,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'sent'
    };
    updateChatMessages(activeChatId, newMessage);
    setInputText('');
  };

  const shareFile = (name: string, size: string) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      senderId: CURRENT_USER_ID,
      file: { name, type: 'file', size },
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'sent'
    };
    updateChatMessages(activeChatId, newMessage);
    setShowAttachMenu(false);
    setShowNotesPicker(false);
  };

  const handleLocalUpload = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        shareFile(file.name, (file.size / 1024 / 1024).toFixed(1) + ' MB');
      }
    };
    input.click();
  };

  const updateChatMessages = (chatId: string, message: Message) => {
    setChats(prevChats => prevChats.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: [...chat.messages, message],
          lastMessage: message.file ? `📎 ${message.file.name}` : (message.text || ''),
          lastMessageTime: 'Just now'
        };
      }
      return chat;
    }));
  };

  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] bg-white rounded-3xl shadow-sm overflow-hidden flex border border-gray-200">

      {/* Sidebar */}
      <div className={`${activeChatId ? 'hidden md:flex' : 'flex'} w-full md:w-80 lg:w-96 flex-col border-r border-gray-200 bg-white`}>
        <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
           <h2 className="text-xl font-black text-gray-800">Communities</h2>
           <button className="p-2 text-gray-600 hover:bg-gray-200 rounded-full transition-all"><Plus className="w-5 h-5" /></button>
        </div>
        <div className="p-3 border-b border-gray-100">
          <div className="relative">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
             <input 
               type="text" 
               placeholder="Search conversations" 
               className="w-full bg-gray-100 text-gray-800 text-sm rounded-xl pl-9 pr-4 py-2.5 focus:outline-none focus:ring-2 focus:ring-blue-100"
               value={searchQuery}
               onChange={(e) => setSearchQuery(e.target.value)}
             />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
           {filteredChats.map(chat => (
             <div 
               key={chat.id}
               onClick={() => setActiveChatId(chat.id)}
               className={`flex items-center p-4 cursor-pointer hover:bg-gray-50 transition-colors border-b border-gray-50 ${activeChatId === chat.id ? 'bg-indigo-50 hover:bg-indigo-50' : ''}`}
             >
               <img src={chat.avatar} alt={chat.name} className="w-12 h-12 rounded-full border border-gray-200 flex-shrink-0" />
               <div className="ml-3 flex-1 overflow-hidden">
                 <div className="flex justify-between items-baseline mb-1">
                    <h3 className="text-sm font-bold text-gray-900 truncate">{chat.name}</h3>
                    <span className="text-[10px] text-gray-400 font-bold">{chat.lastMessageTime}</span>
                 </div>
                 <p className="text-xs text-gray-500 truncate">{chat.lastMessage}</p>
               </div>
             </div>
           ))}
        </div>
      </div>

      {/* Main Chat */}
      <div className={`${!activeChatId ? 'hidden md:flex' : 'flex'} flex-1 flex-col bg-white relative`}>
        {activeChat ? (
          <>
            <div className="p-3 md:p-4 bg-gray-50 border-b border-gray-200 flex justify-between items-center z-10">
               <div className="flex items-center">
                 <button onClick={() => setActiveChatId(null)} className="md:hidden mr-2 p-1 text-gray-600"><ArrowLeft className="w-6 h-6" /></button>
                 <img src={activeChat.avatar} alt={activeChat.name} className="w-10 h-10 rounded-full" />
                 <div className="ml-3">
                    <h3 className="text-gray-800 font-bold text-sm md:text-base">{activeChat.name}</h3>
                    <p className="text-[10px] text-gray-500">{activeChat.type === 'group' ? activeChat.members : 'Online'}</p>
                 </div>
               </div>
               <div className="flex items-center space-x-2 text-gray-400"><MoreVertical className="w-5 h-5" /></div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-4 bg-gray-50/50" style={{ backgroundImage: 'radial-gradient(#e5e7eb 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
              {activeChat.messages.map((msg, idx) => {
                const isMe = msg.senderId === CURRENT_USER_ID;
                return (
                  <div key={idx} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[80%] rounded-2xl p-3 shadow-sm ${isMe ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                      {msg.text && <p className="text-sm leading-relaxed">{msg.text}</p>}
                      {msg.file && (
                        <div className={`flex items-center p-3 rounded-xl mt-1 space-x-3 ${isMe ? 'bg-white/10' : 'bg-gray-100'}`}>
                           <FileText className="w-5 h-5" />
                           <div className="overflow-hidden">
                              <p className="text-xs font-bold truncate">{msg.file.name}</p>
                              <p className="text-[10px] opacity-70">{msg.file.size}</p>
                           </div>
                        </div>
                      )}
                      <div className={`flex items-center justify-end space-x-1 mt-1 text-[9px] opacity-70`}>
                        <span>{msg.timestamp}</span>
                        {isMe && <CheckCheck className="w-3 h-3" />}
                      </div>
                    </div>
                  </div>
                );
              })}
              <div ref={messagesEndRef} />
            </div>

            {/* Input & Attachments */}
            <div className="p-3 md:p-4 bg-white border-t border-gray-100 flex items-end space-x-2 relative">
               {showAttachMenu && (
                 <div ref={attachMenuRef} className="absolute bottom-full left-4 mb-4 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden w-56 animate-fade-up z-20">
                    <div className="p-3 border-b border-gray-50 bg-gray-50 text-[10px] font-black text-gray-400 uppercase tracking-widest">Select Source</div>
                    <button onClick={handleLocalUpload} className="w-full flex items-center space-x-4 p-4 hover:bg-gray-50 text-gray-700 transition-colors">
                       <div className="p-2 bg-blue-50 text-blue-600 rounded-xl"><HardDrive className="w-5 h-5" /></div>
                       <div className="text-left">
                          <p className="text-sm font-bold">Local Files</p>
                          <p className="text-[10px] text-gray-400">Upload from device</p>
                       </div>
                    </button>
                    <button onClick={() => {setShowNotesPicker(true); setShowAttachMenu(false);}} className="w-full flex items-center space-x-4 p-4 hover:bg-gray-50 text-gray-700 transition-colors">
                       <div className="p-2 bg-purple-50 text-purple-600 rounded-xl"><Layout className="w-5 h-5" /></div>
                       <div className="text-left">
                          <p className="text-sm font-bold">My Notes</p>
                          <p className="text-[10px] text-gray-400">Share from library</p>
                       </div>
                    </button>
                 </div>
               )}

               <button onClick={() => setShowAttachMenu(!showAttachMenu)} className={`p-3 rounded-full transition-all mb-1 ${showAttachMenu ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:bg-gray-100'}`}><Paperclip className="w-6 h-6" /></button>
               <div className="flex-1 bg-gray-100 rounded-2xl px-4 py-3 focus-within:ring-2 focus-within:ring-indigo-100 transition-all">
                 <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder="Type a message..." className="w-full bg-transparent border-none focus:outline-none text-sm" />
               </div>
               <button onClick={handleSendMessage} className="p-3 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 shadow-lg active:scale-95 mb-1"><Send className="w-5 h-5" /></button>
            </div>
          </>
        ) : (
          <div className="hidden md:flex flex-1 flex-col items-center justify-center bg-gray-50 text-center p-8">
             <div className="w-40 h-40 bg-white rounded-full flex items-center justify-center mb-6 shadow-sm"><Users className="w-20 text-indigo-100" /></div>
             <h2 className="text-2xl font-black text-gray-800 mb-2">Join the conversation</h2>
             <p className="text-gray-500 max-w-xs text-sm">Collaborate with your peers, share notes, and study better together.</p>
          </div>
        )}

        {/* Notes Picker Modal */}
        {showNotesPicker && (
          <div className="absolute inset-0 z-50 bg-white flex flex-col animate-slide-right">
             <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-gray-50">
                <div className="flex items-center space-x-4">
                   <button onClick={() => setShowNotesPicker(false)} className="p-2 hover:bg-white rounded-xl transition-all"><X className="w-6 h-6 text-gray-400" /></button>
                   <h3 className="text-xl font-black text-gray-800">Share from My Notes</h3>
                </div>
                <div className="relative w-64 hidden sm:block">
                   <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                   <input type="text" placeholder="Filter notes..." className="w-full bg-white border border-gray-200 rounded-xl pl-10 pr-4 py-2 text-xs" />
                </div>
             </div>
             <div className="flex-1 overflow-y-auto p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {RECENT_NOTES.map(note => (
                   <div key={note.id} onClick={() => shareFile(note.title + '.pdf', '0.4 MB')} className="p-5 border-2 border-gray-50 hover:border-indigo-500 hover:bg-indigo-50/30 rounded-3xl transition-all cursor-pointer group">
                      <div className="flex items-center space-x-3 mb-4">
                         <div className="p-2.5 bg-white shadow-sm rounded-xl text-indigo-600 group-hover:scale-110 transition-transform"><FileText className="w-6 h-6" /></div>
                         <div className="overflow-hidden">
                            <h4 className="font-bold text-sm text-gray-800 truncate">{note.title}</h4>
                            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">{note.folder}</p>
                         </div>
                      </div>
                      <p className="text-xs text-gray-400 line-clamp-2 leading-relaxed">{note.content}</p>
                   </div>
                ))}
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Communities;

import React, { useState, useRef, useEffect } from 'react';
import { Search, Bell, ChevronDown, Menu, X } from 'lucide-react';
import { NOTIFICATIONS } from '../constants';

interface HeaderProps {
  toggleSidebar: () => void;
  onNavigate: (page: string) => void;
}

const Header: React.FC<HeaderProps> = ({ toggleSidebar, onNavigate }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const unreadCount = NOTIFICATIONS.filter(n => !n.read).length;

  return (
    <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-gray-200 px-4 py-3 flex items-center justify-between gap-4 animate-fade-up">

      {/* Left: Toggle + Brand */}
      <div className="flex items-center space-x-4 min-w-fit">
        <button 
          onClick={toggleSidebar} 
          className="p-2 hover:bg-gray-100 rounded-xl transition-colors text-gray-600"
        >
          <Menu className="h-6 w-6" />
        </button>

        <div 
          className="flex items-center space-x-2 cursor-pointer"
          onClick={() => onNavigate('Home')}
        >
          <div className="w-8 h-8 bg-blue-500 rounded-full animate-pulse-custom"></div>
          <span className="text-xl font-bold text-gray-800 hidden sm:block">EduDash</span>
        </div>
      </div>

      {/* Middle: Search Bar */}
      <div className="flex-1 max-w-2xl px-4 hidden md:block">
        <div className="relative group">
          <span className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
          </span>
          <input
            type="text"
            className="w-full py-2.5 pl-10 pr-4 bg-gray-50 border border-transparent focus:bg-white focus:border-blue-200 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-50 transition-all duration-300"
            placeholder="Search for notes, tests, or communities..."
          />
        </div>
      </div>

      {/* Right: Actions & Profile */}
      <div className="flex items-center space-x-3 sm:space-x-6 min-w-fit justify-end relative">

        {/* Notification Bell */}
        <div className="relative" ref={notifRef}>
          <button 
            onClick={() => setShowNotifications(!showNotifications)}
            className={`hidden md:block p-2 rounded-full transition-colors relative ${showNotifications ? 'bg-blue-50 text-blue-600' : 'bg-gray-50 hover:bg-gray-100 text-gray-600'}`}
          >
            <Bell className="h-5 w-5" />
            {unreadCount > 0 && (
              <span className="absolute top-1 right-1.5 block h-2 w-2 rounded-full bg-red-500 ring-2 ring-white animate-pulse-custom"></span>
            )}
          </button>

          {/* Notification Dropdown */}
          {showNotifications && (
            <div className="absolute right-0 mt-3 w-80 bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden animate-fade-up origin-top-right">
              <div className="p-4 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-800">Notifications</h3>
                <span className="text-xs text-blue-600 font-medium">{unreadCount} unread</span>
              </div>
              <div className="max-h-[300px] overflow-y-auto">
                {NOTIFICATIONS.slice(0, 3).map(notif => (
                   <div key={notif.id} className="p-4 border-b border-gray-50 hover:bg-gray-50 transition-colors cursor-pointer" onClick={() => {onNavigate('Notifications'); setShowNotifications(false);}}>
                      <div className="flex justify-between items-start mb-1">
                        <span className={`text-sm font-semibold ${!notif.read ? 'text-gray-900' : 'text-gray-600'}`}>{notif.title}</span>
                        <span className="text-[10px] text-gray-400">{notif.time}</span>
                      </div>
                      <p className="text-xs text-gray-500 line-clamp-2">{notif.message}</p>
                   </div>
                ))}
              </div>
              <div className="p-3 bg-gray-50 text-center border-t border-gray-100">
                <button 
                  onClick={() => {
                    onNavigate('Notifications');
                    setShowNotifications(false);
                  }}
                  className="text-sm text-blue-600 font-semibold hover:text-blue-800 transition-colors"
                >
                  See all notifications
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Profile */}
        <div 
          onClick={() => onNavigate('Profile')}
          className="flex items-center space-x-3 cursor-pointer p-1.5 rounded-xl hover:bg-gray-50 transition-colors border border-transparent hover:border-gray-200"
        >
          <img
            className="h-9 w-9 rounded-full border border-gray-200"
            src="https://ui-avatars.com/api/?name=Vivek&background=4F46E5&color=fff"
            alt="Vivek"
          />
          <div className="hidden lg:block text-left">
            <p className="text-sm font-semibold text-gray-800 leading-none">Vivek</p>
            <p className="text-xs text-gray-500 mt-0.5">Student</p>
          </div>
          <ChevronDown className="h-4 w-4 text-gray-400 hidden lg:block" />
        </div>
      </div>
    </header>
  );
};

