import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ParticleBackground from './components/ParticleBackground';

// Pages
import Home from './components/Home';
import MyNotes from './components/MyNotes';
import TestsQuizzes from './components/TestsQuizzes';
import Communities from './components/Communities';
import AITutor from './components/AITutor';
import Settings from './components/Settings';
import NotificationsPage from './components/NotificationsPage';
import ProfilePage from './components/ProfilePage';
import { GraduationCap, Briefcase } from 'lucide-react';

const App: React.FC = () => {
  const [mounted, setMounted] = useState(false);
  const [currentPage, setCurrentPage] = useState('Home');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [userRole, setUserRole] = useState<'student' | 'teacher' | null>(() => {
    return localStorage.getItem('eduDashRole') as 'student' | 'teacher' | null;
  });

  useEffect(() => {
    setMounted(true);
  }, []);

  const selectRole = (role: 'student' | 'teacher') => {
    setUserRole(role);
    localStorage.setItem('eduDashRole', role);
  };

  const toggleSidebar = () => {
    if (window.innerWidth < 1024) {
      setIsMobileMenuOpen(!isMobileMenuOpen);
    } else {
      setIsSidebarCollapsed(!isSidebarCollapsed);
    }
  };

  const handleNavigate = (page: string) => {
    setCurrentPage(page);
    setIsMobileMenuOpen(false);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'Home': return <Home onNavigate={handleNavigate} />;
      case 'My Notes': return <MyNotes />;
      case 'Tests & Quizzes': return <TestsQuizzes />;
      case 'Communities': return <Communities />;
      case 'AI Tutor': return <AITutor />;
      case 'Settings': return <Settings role={userRole || 'student'} />;
      case 'Notifications': return <NotificationsPage />;
      case 'Profile': return <ProfilePage role={userRole || 'student'} />;
      default: return <Home onNavigate={handleNavigate} />;
    }
  };

  if (!userRole && mounted) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6 font-student relative overflow-hidden">
        <ParticleBackground />
        <div className="bg-white p-10 rounded-[3rem] shadow-2xl max-w-2xl w-full text-center z-10 animate-fade-up border border-gray-100">
           <div className="w-16 h-16 bg-blue-500 rounded-full mx-auto mb-6 animate-pulse-custom"></div>
           <h1 className="text-4xl font-black text-gray-900 mb-4">Welcome to EduDash AI</h1>
           <p className="text-gray-500 mb-10 text-lg">Please select your primary role to customize your study experience.</p>

           <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <button 
                onClick={() => selectRole('student')}
                className="group p-8 bg-white border-2 border-gray-100 rounded-[2.5rem] hover:border-blue-500 hover:bg-blue-50 transition-all flex flex-col items-center text-center shadow-sm hover:shadow-xl"
              >
                 <div className="p-5 bg-blue-100 rounded-3xl text-blue-600 mb-4 group-hover:scale-110 transition-transform">
                    <GraduationCap className="w-12 h-12" />
                 </div>
                 <h2 className="text-xl font-black text-gray-800">Student</h2>
                 <p className="text-xs text-gray-500 mt-2">I want to track my notes, study for exams, and join communities.</p>
              </button>

              <button 
                onClick={() => selectRole('teacher')}
                className="group p-8 bg-white border-2 border-gray-100 rounded-[2.5rem] hover:border-indigo-500 hover:bg-indigo-50 transition-all flex flex-col items-center text-center shadow-sm hover:shadow-xl"
              >
                 <div className="p-5 bg-indigo-100 rounded-3xl text-indigo-600 mb-4 group-hover:scale-110 transition-transform">
                    <Briefcase className="w-12 h-12" />
                 </div>
                 <h2 className="text-xl font-black text-gray-800">Teacher</h2>
                 <p className="text-xs text-gray-500 mt-2">I want to share material, assist students, and manage groups.</p>
              </button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen bg-gray-50 font-student transition-opacity duration-500 flex flex-col ${mounted ? 'opacity-100' : 'opacity-0'}`}>
      <div className="fixed inset-0 pointer-events-none z-0">
         <ParticleBackground />
      </div>

      <Header toggleSidebar={toggleSidebar} onNavigate={handleNavigate} />

      <div className="flex flex-1 relative z-10 max-w-[1920px] mx-auto w-full">
        {isMobileMenuOpen && (
          <div className="fixed inset-0 bg-black/50 z-40 lg:hidden transition-opacity" onClick={() => setIsMobileMenuOpen(false)} />
        )}

        <div className={`fixed lg:sticky top-[73px] z-50 h-[calc(100vh-73px)] transition-transform duration-300 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'} lg:block`}>
           <Sidebar collapsed={isSidebarCollapsed} activePage={currentPage} onNavigate={handleNavigate} />
        </div>

        <main className={`flex-1 p-3 md:p-6 lg:p-8 overflow-y-auto h-[calc(100vh-73px)] scroll-smooth`}>
          <div className="max-w-7xl mx-auto animate-slide-right">
            {renderPage()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { NAV_ITEMS } from '../constants';

interface SidebarProps {
  collapsed: boolean;
  activePage: string;
  onNavigate: (page: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ collapsed, activePage, onNavigate }) => {
  return (
    <aside 
      className={`bg-white shadow-sm h-full flex flex-col py-6 overflow-y-auto border-r border-gray-100 transition-all duration-300 ease-in-out no-print
      ${collapsed ? 'w-20 items-center' : 'w-72 lg:w-64 px-4'}
      `}
    >
      <nav className="space-y-1.5 w-full">
        {NAV_ITEMS.map((item) => (
          <button
            key={item.name}
            onClick={() => onNavigate(item.name)}
            title={collapsed ? item.name : ''}
            className={`flex items-center transition-all duration-300 rounded-xl group relative
              ${collapsed ? 'justify-center w-12 h-12 mx-auto' : 'w-full px-4 py-3.5 space-x-3'}
              ${activePage === item.name
                ? 'bg-blue-50 text-blue-600 shadow-sm shadow-blue-50'
                : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }
            `}
          >
            <item.icon 
              className={`transition-colors duration-300 ${collapsed ? 'w-6 h-6' : 'w-5 h-5'} 
              ${activePage === item.name ? 'text-blue-600' : 'text-gray-500 group-hover:text-gray-900'}`} 
            />

            {!collapsed && (
              <span className={`font-semibold text-sm whitespace-nowrap transition-opacity duration-300 ${collapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
                {item.name}
              </span>
            )}

            {/* Tooltip for collapsed state */}
            {collapsed && (
               <div className="absolute left-full top-1/2 -translate-y-1/2 ml-2 bg-gray-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50">
                 {item.name}
               </div>
            )}

            {/* Active Indicator Bar */}
            {activePage === item.name && !collapsed && (
              <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-blue-600 rounded-l-full"></div>
            )}
          </button>
        ))}
      </nav>
    </aside>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { RECENT_NOTES } from '../constants';
import { Note } from '../types';
import { 
  Folder, 
  ChevronLeft, 
  Plus, 
  MoreVertical, 
  Search,
  Bold,
  Italic,
  Underline,
  List,
  AlignLeft,
  FileText,
  Upload,
  Printer,
  Share2,
  FileCheck,
  Eye
} from 'lucide-react';

const MyNotes: React.FC = () => {
  const [activeFolder, setActiveFolder] = useState<string | null>(null);
  const [notes, setNotes] = useState<Note[]>(RECENT_NOTES);
  const [activeNoteId, setActiveNoteId] = useState<number | null>(null);

  const folders = Array.from(new Set<string>(notes.map(n => n.folder))).sort();
  const allFolders = ['Biology', 'History', 'Math', 'Design Thinking', 'Other']; 
  const uniqueFolders = Array.from(new Set<string>([...allFolders, ...folders]));

  const filteredNotes = activeFolder 
    ? notes.filter(n => n.folder === activeFolder) 
    : [];

  const activeNote = notes.find(n => n.id === activeNoteId);

  const handleCreateNote = () => {
    if (!activeFolder) return;
    const newNote: Note = {
      id: Date.now(),
      title: 'New Page',
      folder: activeFolder,
      content: '',
      color: 'gray',
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    };
    setNotes([newNote, ...notes]);
    setActiveNoteId(newNote.id);
  };

  const handleUpdateNote = (id: number, field: keyof Note, value: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, [field]: value } : n));
  };

  const handleUploadPDF = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/pdf';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file && activeFolder) {
        // In a real app, we'd upload this to storage.
        // For simulation, we create a pseudo-note representing the PDF.
        const newNote: Note = {
          id: Date.now(),
          title: file.name,
          folder: activeFolder,
          content: `[This is a PDF viewer simulation for: ${file.name}]`,
          color: 'blue',
          date: 'Just now'
        };
        setNotes([newNote, ...notes]);
        setActiveNoteId(newNote.id);
      }
    };
    input.click();
  };

  const handlePrintPDF = () => {
    window.print();
  };

  const handleOpenInNewTab = () => {
     if (!activeNote) return;
     // Simulating opening the PDF in browser's built-in viewer
     const blob = new Blob([activeNote.content], { type: 'text/plain' });
     const url = URL.createObjectURL(blob);
     window.open(url, '_blank');
  };

  const getFolderColor = (folder: string) => {
    switch(folder) {
        case 'Biology': return 'bg-green-100 text-green-700';
        case 'History': return 'bg-amber-100 text-amber-700';
        case 'Math': return 'bg-purple-100 text-purple-700';
        case 'Design Thinking': return 'bg-orange-100 text-orange-700';
        default: return 'bg-gray-100 text-gray-700';
    }
  };

  if (!activeFolder) {
    return (
      <div className="animate-fade-up h-full flex flex-col no-print">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
          <div>
            <h2 className="text-3xl font-black text-gray-800">My Notebooks</h2>
            <p className="text-sm text-gray-500 font-medium">Manage your personal study material</p>
          </div>
          <div className="flex space-x-3 w-full sm:w-auto">
            <button 
              onClick={() => setActiveFolder('Other')}
              className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
            >
              <Plus className="w-5 h-5" />
              <span>Create Note</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
          {uniqueFolders.map((folder) => {
             const count = notes.filter(n => n.folder === folder).length;
             return (
               <div 
                 key={folder}
                 onClick={() => { setActiveFolder(folder); setActiveNoteId(null); }}
                 className="bg-white p-6 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all cursor-pointer group flex flex-col items-center justify-center text-center aspect-square border border-transparent hover:border-blue-100 relative overflow-hidden"
               >
                 <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mb-4 transition-transform group-hover:scale-110 group-hover:rotate-6 ${getFolderColor(folder)}`}>
                   <Folder className="w-10 h-10 fill-current opacity-80" />
                 </div>
                 <h3 className="text-lg font-bold text-gray-800 group-hover:text-blue-600 transition-colors truncate w-full px-2">{folder}</h3>
                 <p className="text-sm text-gray-500 mt-1 font-medium">{count} {count === 1 ? 'file' : 'files'}</p>
                 <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                    <div className="p-2 bg-gray-50 rounded-full hover:bg-gray-100">
                       <MoreVertical className="w-4 h-4 text-gray-400" />
                    </div>
                 </div>
               </div>
             );
          })}
          <div className="border-4 border-dashed border-gray-100 p-6 rounded-[2.5rem] flex flex-col items-center justify-center text-center aspect-square cursor-pointer hover:bg-white hover:border-blue-200 transition-all group">
             <div className="p-4 bg-gray-50 rounded-3xl group-hover:bg-blue-50 transition-colors">
               <Plus className="w-12 h-12 text-gray-300 group-hover:text-blue-500" />
             </div>
             <span className="font-bold text-gray-400 group-hover:text-blue-500 mt-4">Add Project</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] flex bg-white rounded-[2rem] shadow-xl overflow-hidden border border-gray-100 note-container">

      <div className="w-72 bg-gray-50 border-r border-gray-200 flex flex-col flex-shrink-0 no-print">
        <div className="p-5 border-b border-gray-200 flex items-center space-x-3 bg-white">
           <button onClick={() => setActiveFolder(null)} className="p-2 hover:bg-gray-100 rounded-xl text-gray-500 transition-all hover:scale-110">
             <ChevronLeft className="w-5 h-5" />
           </button>
           <span className="font-black text-gray-800 truncate text-lg">{activeFolder}</span>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-1">
           {filteredNotes.length === 0 ? (
             <div className="p-8 text-center text-gray-400 text-sm italic">Folder is empty</div>
           ) : (
             filteredNotes.map(note => (
               <div 
                 key={note.id}
                 onClick={() => setActiveNoteId(note.id)}
                 className={`p-4 rounded-2xl cursor-pointer transition-all ${activeNoteId === note.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'hover:bg-white text-gray-700'}`}
               >
                 <div className="flex items-center space-x-3">
                   <FileText className={`w-4 h-4 flex-shrink-0 ${activeNoteId === note.id ? 'text-indigo-100' : 'text-gray-400'}`} />
                   <h4 className="font-bold text-sm truncate">{note.title || 'Untitled Page'}</h4>
                 </div>
                 <p className={`text-[10px] mt-1 truncate ${activeNoteId === note.id ? 'text-indigo-200' : 'text-gray-400'}`}>
                    {note.date} • {note.content.substring(0, 30) || 'Empty note'}
                 </p>
               </div>
             ))
           )}
        </div>

        <div className="p-4 bg-white border-t border-gray-100 space-y-2">
           <button 
             onClick={handleUploadPDF}
             className="w-full py-3 flex items-center justify-center space-x-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-2xl transition-all font-bold text-sm border border-indigo-100"
           >
             <Upload className="w-4 h-4" />
             <span>Upload PDF</span>
           </button>
           <button 
             onClick={handleCreateNote}
             className="w-full py-3 flex items-center justify-center space-x-3 bg-gray-900 hover:bg-black text-white rounded-2xl transition-all font-bold text-sm"
           >
             <Plus className="w-4 h-4" />
             <span>New Page</span>
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white overflow-hidden">
         {activeNote ? (
           <>
             <div className="h-16 border-b border-gray-100 flex items-center justify-between px-6 no-print">
                <div className="flex items-center space-x-1">
                  {[Bold, Italic, Underline, List, AlignLeft].map((Icon, i) => (
                    <button key={i} className="p-2.5 text-gray-400 hover:bg-gray-100 hover:text-gray-800 rounded-xl transition-all">
                      <Icon className="w-4 h-4" />
                    </button>
                  ))}
                </div>
                <div className="flex items-center space-x-3">
                   <button 
                     onClick={handleOpenInNewTab}
                     className="flex items-center space-x-2 px-4 py-2 bg-gray-50 text-gray-600 rounded-xl font-bold text-xs hover:bg-gray-100 transition-all"
                   >
                     <Eye className="w-3.5 h-3.5" />
                     <span>Browser View</span>
                   </button>
                   <button 
                     onClick={handlePrintPDF}
                     className="flex items-center space-x-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-all"
                   >
                     <Printer className="w-3.5 h-3.5" />
                     <span>Print PDF</span>
                   </button>
                   <button className="flex items-center space-x-2 px-4 py-2 bg-green-50 text-green-600 rounded-xl font-bold text-xs hover:bg-green-100 transition-all">
                     <Share2 className="w-3.5 h-3.5" />
                     <span>Share</span>
                   </button>
                </div>
             </div>

             <div className="flex-1 overflow-y-auto p-10 md:p-16 max-w-4xl mx-auto w-full font-student">
                <div className="flex items-center justify-between mb-8 no-print">
                   <span className="bg-gray-100 text-gray-500 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full">{activeNote.folder}</span>
                   <span className="text-[10px] text-gray-400 font-medium">Last Edited: {activeNote.date}</span>
                </div>
                <input 
                  type="text" 
                  value={activeNote.title}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'title', e.target.value)}
                  placeholder="Untitled Page"
                  className="w-full text-5xl font-black text-gray-900 placeholder-gray-100 border-none focus:outline-none focus:ring-0 bg-transparent mb-10 selection:bg-blue-100"
                />
                <textarea
                  value={activeNote.content}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'content', e.target.value)}
                  placeholder="The page is empty. Start typing your thoughts or paste research here..."
                  className="w-full h-full min-h-[500px] resize-none text-gray-700 text-xl leading-relaxed border-none focus:outline-none focus:ring-0 bg-transparent selection:bg-blue-100 whitespace-pre-wrap"
                />
             </div>
           </>
         ) : (
           <div className="flex-1 flex flex-col items-center justify-center text-gray-200 no-print">
             <div className="w-32 h-32 bg-gray-50 rounded-[2.5rem] flex items-center justify-center mb-6">
                <FileCheck className="w-16 h-16 opacity-10" />
             </div>
             <p className="text-xl font-black text-gray-400">Select a note to begin editing</p>
             <p className="text-sm font-bold text-gray-300">Your ideas deserve to be written down.</p>
           </div>
         )}
      </div>
    </div>
  );
};

export default MyNotes;

