  const selectRole = (role: 'student' | 'teacher') => {
    setUserRole(role);
    localStorage.setItem('studyBuddyRole', role);
  };

  const toggleSidebar = () => {
    if (window.innerWidth < 1024) {
      setIsMobileMenuOpen(!isMobileMenuOpen);
    } else {
      setIsSidebarCollapsed(!isSidebarCollapsed);
    }
  };

  const handleNavigate = (page: string) => {
    setCurrentPage(page);
    setIsMobileMenuOpen(false);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'Home': return <Home onNavigate={handleNavigate} />;
      case 'My Notes': return <MyNotes />;
      case 'Tests & Quizzes': return <TestsQuizzes role={userRole || 'student'} />;
      case 'Communities': return <Communities role={userRole || 'student'} />;
      case 'AI Tutor': return <AITutor />;
      case 'Settings': return <Settings role={userRole || 'student'} />;
      case 'Notifications': return <NotificationsPage />;
      case 'Profile': return <ProfilePage role={userRole || 'student'} />;
      default: return <Home onNavigate={handleNavigate} />;
    }
  };

  if (!userRole && mounted) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6 font-student relative overflow-hidden">
        <ParticleBackground />
        <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl max-w-2xl w-full text-center z-10 animate-fade-up border border-gray-100">
           <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] mx-auto mb-8 flex items-center justify-center shadow-xl shadow-indigo-100 animate-pulse-custom">
              <Sparkles className="text-white w-10 h-10" />
           </div>
           <h1 className="text-5xl font-black text-gray-900 mb-4 tracking-tight">StudyBuddy</h1>
           <p className="text-gray-500 mb-12 text-lg">AI-Driven Study & Community Collaboration Platform. <br/>Select your role to begin your journey.</p>

           <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <button 
                onClick={() => selectRole('student')}
                className="group p-8 bg-white border-4 border-gray-50 rounded-[3rem] hover:border-indigo-600 hover:bg-indigo-50/30 transition-all flex flex-col items-center text-center shadow-lg hover:shadow-2xl active:scale-95"
              >
                 <div className="p-6 bg-indigo-100 rounded-[2rem] text-indigo-600 mb-6 group-hover:scale-110 transition-transform">
                    <GraduationCap className="w-14 h-14" />
                 </div>
                 <h2 className="text-2xl font-black text-gray-800">Student</h2>
                 <p className="text-xs text-gray-400 mt-2 font-medium">I want to learn, track notes, and join study groups.</p>
              </button>

              <button 
                onClick={() => selectRole('teacher')}
                className="group p-8 bg-white border-4 border-gray-50 rounded-[3rem] hover:border-blue-600 hover:bg-blue-50/30 transition-all flex flex-col items-center text-center shadow-lg hover:shadow-2xl active:scale-95"
              >
                 <div className="p-6 bg-blue-100 rounded-[2rem] text-blue-600 mb-6 group-hover:scale-110 transition-transform">
                    <Briefcase className="w-14 h-14" />
                 </div>
                 <h2 className="text-2xl font-black text-gray-800">Teacher</h2>
                 <p className="text-xs text-gray-400 mt-2 font-medium">I want to create tests, share materials, and manage classes.</p>
              </button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen bg-gray-50 font-student transition-opacity duration-500 flex flex-col ${mounted ? 'opacity-100' : 'opacity-0'}`}>
      <div className="fixed inset-0 pointer-events-none z-0">
         <ParticleBackground />
      </div>

      <Header toggleSidebar={toggleSidebar} onNavigate={handleNavigate} />

      <div className="flex flex-1 relative z-10 max-w-[1920px] mx-auto w-full">
        {isMobileMenuOpen && (
          <div className="fixed inset-0 bg-black/50 z-40 lg:hidden transition-opacity" onClick={() => setIsMobileMenuOpen(false)} />
        )}

        <div className={`fixed lg:sticky top-[73px] z-50 h-[calc(100vh-73px)] transition-transform duration-300 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'} lg:block`}>
           <Sidebar collapsed={isSidebarCollapsed} activePage={currentPage} onNavigate={handleNavigate} />
        </div>

        <main className={`flex-1 p-3 md:p-6 lg:p-8 overflow-y-auto h-[calc(100vh-73px)] scroll-smooth`}>
          <div className="max-w-7xl mx-auto animate-slide-right">
            {renderPage()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Search, Bell, ChevronDown, Menu, Sparkles } from 'lucide-react';
import { NOTIFICATIONS } from '../constants';

interface HeaderProps {
  toggleSidebar: () => void;
  onNavigate: (page: string) => void;
}

const Header: React.FC<HeaderProps> = ({ toggleSidebar, onNavigate }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const unreadCount = NOTIFICATIONS.filter(n => !n.read).length;

  return (
    <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-gray-100 px-4 py-3 flex items-center justify-between gap-4 animate-fade-up">

      <div className="flex items-center space-x-4 min-w-fit">
        <button 
          onClick={toggleSidebar} 
          className="p-2 hover:bg-gray-100 rounded-xl transition-colors text-gray-600"
        >
          <Menu className="h-6 w-6" />
        </button>

        <div 
          className="flex items-center space-x-2 cursor-pointer group"
          onClick={() => onNavigate('Home')}
        >
          <div className="w-9 h-9 bg-indigo-600 rounded-[0.75rem] flex items-center justify-center text-white shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
             <Sparkles className="w-5 h-5" />
          </div>
          <span className="text-2xl font-black text-gray-800 hidden sm:block tracking-tight">StudyBuddy</span>
        </div>
      </div>

      <div className="flex-1 max-w-2xl px-4 hidden md:block">
        <div className="relative group">
          <span className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none">
            <Search className="h-5 w-5 text-gray-300 group-focus-within:text-indigo-500 transition-colors" />
          </span>
          <input
            type="text"
            className="w-full py-3 pl-12 pr-4 bg-gray-50 border border-transparent focus:bg-white focus:border-indigo-100 rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-50 transition-all duration-300 font-medium"
            placeholder="Search notes, flashcards, groups..."
          />
        </div>
      </div>

      <div className="flex items-center space-x-3 sm:space-x-6 min-w-fit justify-end relative">
        <div className="relative" ref={notifRef}>
          <button 
            onClick={() => setShowNotifications(!showNotifications)}
            className={`hidden md:block p-2.5 rounded-xl transition-colors relative ${showNotifications ? 'bg-indigo-50 text-indigo-600' : 'bg-gray-50 hover:bg-gray-100 text-gray-600'}`}
          >
            <Bell className="h-5 w-5" />
            {unreadCount > 0 && (
              <span className="absolute top-1 right-1.5 block h-2.5 w-2.5 rounded-full bg-red-500 ring-4 ring-white"></span>
            )}
          </button>

          {showNotifications && (
            <div className="absolute right-0 mt-3 w-80 bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden animate-fade-up origin-top-right">
              <div className="p-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-black text-gray-800">Alerts</h3>
                <span className="text-[10px] font-black uppercase text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{unreadCount} New</span>
              </div>
              <div className="max-h-[350px] overflow-y-auto">
                {NOTIFICATIONS.map(notif => (
                   <div key={notif.id} className="p-5 border-b border-gray-50 hover:bg-indigo-50/30 transition-colors cursor-pointer" onClick={() => {onNavigate('Notifications'); setShowNotifications(false);}}>
                      <div className="flex justify-between items-start mb-1">
                        <span className={`text-sm font-bold ${!notif.read ? 'text-gray-900' : 'text-gray-500'}`}>{notif.title}</span>
                        <span className="text-[10px] font-bold text-gray-400">{notif.time}</span>
                      </div>
                      <p className="text-xs text-gray-500 line-clamp-2 leading-relaxed">{notif.message}</p>
                   </div>
                ))}
              </div>
              <div className="p-4 bg-gray-50 text-center">
                <button onClick={() => {onNavigate('Notifications'); setShowNotifications(false);}} className="text-xs font-black text-indigo-600 hover:underline">View All Notifications</button>
              </div>
            </div>
          )}
        </div>

        <div 
          onClick={() => onNavigate('Profile')}
          className="flex items-center space-x-3 cursor-pointer p-1.5 rounded-2xl hover:bg-gray-50 transition-colors"
        >
          <img
            className="h-10 w-10 rounded-2xl border-2 border-white shadow-sm"
            src="https://ui-avatars.com/api/?name=Vivek+Pawar&background=4F46E5&color=fff"
            alt="Vivek"
          />
          <div className="hidden lg:block text-left">
            <p className="text-sm font-black text-gray-800 leading-none">Vivek Pawar</p>
            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Student</p>
          </div>
          <ChevronDown className="h-4 w-4 text-gray-400 hidden lg:block" />
        </div>
      </div>
    </header>
  );
};

