import React, { useState } from 'react';
import { RECENT_NOTES } from '../constants';
import { Note } from '../types';
import { 
  Folder, 
  ChevronLeft, 
  Plus, 
  MoreVertical, 
  Search,
  Bold,
  Italic,
  Underline,
  List,
  AlignLeft,
  FileText,
  Upload,
  Printer,
  Share2,
  FileCheck,
  Eye,
  Sparkles,
  Zap,
  BookOpen
} from 'lucide-react';

const MyNotes: React.FC = () => {
  const [activeFolder, setActiveFolder] = useState<string | null>(null);
  const [notes, setNotes] = useState<Note[]>(RECENT_NOTES);
  const [activeNoteId, setActiveNoteId] = useState<number | null>(null);
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [aiResult, setAiResult] = useState<{type: 'summary' | 'flashcards', content: string} | null>(null);

  const folders = Array.from(new Set<string>(notes.map(n => n.folder))).sort();
  const allFolders = ['Biology', 'History', 'Math', 'Design Thinking', 'Other']; 
  const uniqueFolders = Array.from(new Set<string>([...allFolders, ...folders]));

  const filteredNotes = activeFolder ? notes.filter(n => n.folder === activeFolder) : [];
  const activeNote = notes.find(n => n.id === activeNoteId);

  const handleCreateNote = () => {
    if (!activeFolder) return;
    const newNote: Note = {
      id: Date.now(),
      title: 'New Page',
      folder: activeFolder,
      content: '',
      color: 'gray',
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    };
    setNotes([newNote, ...notes]);
    setActiveNoteId(newNote.id);
  };

  const handleUpdateNote = (id: number, field: keyof Note, value: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, [field]: value } : n));
  };

  const handleGenerateAI = (type: 'summary' | 'flashcards') => {
    if (!activeNote?.content) return;
    setIsProcessingAI(true);
    setAiResult(null);

    // Simulate Gemini API processing
    setTimeout(() => {
      setIsProcessingAI(false);
      if (type === 'summary') {
        setAiResult({ type: 'summary', content: `AI SUMMARY:\nThis note discusses the core concepts of ${activeNote.title}. Key takeaways include structural properties and functional impacts within the ${activeNote.folder} context.` });
      } else {
        setAiResult({ type: 'flashcards', content: `FLASHCARDS:\nQ: What is the main theme?\nA: ${activeNote.title}\n\nQ: Key detail 1?\nA: Structural integrity is paramount.` });
      }
    }, 2000);
  };

  const handlePrintPDF = () => window.print();

  const handleOpenInNewTab = () => {
     if (!activeNote) return;
     const blob = new Blob([activeNote.content], { type: 'text/plain' });
     const url = URL.createObjectURL(blob);
     window.open(url, '_blank');
  };

  const getFolderColor = (folder: string) => {
    switch(folder) {
        case 'Biology': return 'bg-green-100 text-green-700';
        case 'History': return 'bg-amber-100 text-amber-700';
        case 'Math': return 'bg-purple-100 text-purple-700';
        case 'Design Thinking': return 'bg-orange-100 text-orange-700';
        default: return 'bg-gray-100 text-gray-700';
    }
  };

  if (!activeFolder) {
    return (
      <div className="animate-fade-up h-full flex flex-col no-print font-student">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
          <div>
            <h2 className="text-4xl font-black text-gray-800">My Notes</h2>
            <p className="text-sm text-gray-400 font-bold uppercase tracking-widest mt-1">Resource Library</p>
          </div>
          <button 
            onClick={() => setActiveFolder('Other')}
            className="bg-indigo-600 text-white px-8 py-4 rounded-3xl font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 flex items-center space-x-3"
          >
            <Plus className="w-5 h-5" />
            <span>Create Folder</span>
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-8">
          {uniqueFolders.map((folder) => {
             const count = notes.filter(n => n.folder === folder).length;
             return (
               <div 
                 key={folder}
                 onClick={() => { setActiveFolder(folder); setActiveNoteId(null); }}
                 className="bg-white p-8 rounded-[3rem] shadow-sm hover:shadow-2xl transition-all cursor-pointer group flex flex-col items-center justify-center text-center aspect-square border-4 border-transparent hover:border-indigo-50 relative overflow-hidden"
               >
                 <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center mb-6 transition-transform group-hover:scale-110 group-hover:-rotate-3 ${getFolderColor(folder)} shadow-sm`}>
                   <Folder className="w-12 h-12 fill-current" />
                 </div>
                 <h3 className="text-xl font-black text-gray-800 group-hover:text-indigo-600 transition-colors truncate w-full px-2">{folder}</h3>
                 <p className="text-xs font-bold text-gray-400 mt-1 uppercase tracking-tighter">{count} {count === 1 ? 'File' : 'Files'}</p>
               </div>
             );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-up h-[calc(100vh-140px)] flex bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-gray-100 note-container font-student">

      <div className="w-80 bg-gray-50/50 border-r border-gray-100 flex flex-col flex-shrink-0 no-print">
        <div className="p-6 border-b border-gray-100 flex items-center space-x-3 bg-white">
           <button onClick={() => setActiveFolder(null)} className="p-2.5 hover:bg-gray-100 rounded-2xl text-gray-500 transition-all">
             <ChevronLeft className="w-5 h-5" />
           </button>
           <span className="font-black text-gray-800 truncate text-xl">{activeFolder}</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2">
           {filteredNotes.map(note => (
             <div 
               key={note.id}
               onClick={() => setActiveNoteId(note.id)}
               className={`p-5 rounded-[2rem] cursor-pointer transition-all ${activeNoteId === note.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'hover:bg-white text-gray-700'}`}
             >
               <div className="flex items-center space-x-3">
                 <FileText className={`w-4 h-4 flex-shrink-0 ${activeNoteId === note.id ? 'text-indigo-200' : 'text-gray-400'}`} />
                 <h4 className="font-bold text-sm truncate">{note.title || 'Untitled'}</h4>
               </div>
               <p className={`text-[10px] mt-1 font-medium truncate ${activeNoteId === note.id ? 'text-indigo-200' : 'text-gray-400'}`}>
                  {note.date} • {note.content.substring(0, 30) || 'Empty note...'}
               </p>
             </div>
           ))}
        </div>

        <div className="p-5 bg-white border-t border-gray-100 space-y-3">
           <button onClick={() => {}} className="w-full py-4 flex items-center justify-center space-x-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-3xl transition-all font-black text-xs uppercase tracking-widest border border-indigo-100">
             <Upload className="w-4 h-4" />
             <span>Upload PDF</span>
           </button>
           <button onClick={handleCreateNote} className="w-full py-4 flex items-center justify-center space-x-3 bg-gray-900 hover:bg-black text-white rounded-3xl transition-all font-black text-xs uppercase tracking-widest">
             <Plus className="w-4 h-4" />
             <span>New Page</span>
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white overflow-hidden relative">
         {activeNote ? (
           <>
             {/* Note Toolbar */}
             <div className="h-20 border-b border-gray-50 flex items-center justify-between px-8 no-print bg-white/50 backdrop-blur-sm z-10">
                <div className="flex items-center space-x-2">
                   <button onClick={() => handleGenerateAI('summary')} className="flex items-center space-x-2 px-5 py-2.5 bg-indigo-50 text-indigo-700 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-100 transition-all">
                      <Sparkles className="w-4 h-4" />
                      <span>AI Summary</span>
                   </button>
                   <button onClick={() => handleGenerateAI('flashcards')} className="flex items-center space-x-2 px-5 py-2.5 bg-orange-50 text-orange-700 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-100 transition-all">
                      <Zap className="w-4 h-4" />
                      <span>Flashcards</span>
                   </button>
                </div>
                <div className="flex items-center space-x-3">
                   <button onClick={handleOpenInNewTab} className="p-3 text-gray-400 hover:bg-gray-50 rounded-2xl transition-all"><Eye className="w-5 h-5" /></button>
                   <button onClick={handlePrintPDF} className="p-3 text-gray-400 hover:bg-gray-50 rounded-2xl transition-all"><Printer className="w-5 h-5" /></button>
                   <button className="px-6 py-2.5 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all">
                      <Share2 className="w-4 h-4 mr-2 inline" /> Share
                   </button>
                </div>
             </div>

             {/* AI Output Overlay */}
             {aiResult && (
               <div className="absolute top-24 right-8 w-80 bg-white rounded-[2rem] shadow-2xl border border-indigo-100 z-20 animate-fade-up overflow-hidden">
                  <div className={`p-4 flex justify-between items-center ${aiResult.type === 'summary' ? 'bg-indigo-600 text-white' : 'bg-orange-500 text-white'}`}>
                     <span className="text-[10px] font-black uppercase tracking-[0.2em]">{aiResult.type}</span>
                     <button onClick={() => setAiResult(null)} className="p-1 hover:bg-white/20 rounded-lg"><Eye className="w-4 h-4" /></button>
                  </div>
                  <div className="p-6">
                     <p className="text-sm text-gray-700 leading-relaxed font-medium whitespace-pre-wrap">{aiResult.content}</p>
                     <button onClick={() => handleUpdateNote(activeNote.id, 'content', activeNote.content + '\n\n' + aiResult.content)} className="mt-6 w-full py-3 bg-gray-50 text-gray-800 rounded-2xl font-black text-[10px] uppercase hover:bg-gray-100">Insert into Note</button>
                  </div>
               </div>
             )}

             {isProcessingAI && (
               <div className="absolute inset-0 bg-white/60 backdrop-blur-sm z-30 flex items-center justify-center">
                  <div className="text-center">
                     <div className="w-16 h-16 border-4 border-indigo-600/20 border-t-indigo-600 rounded-full animate-spin mx-auto mb-4"></div>
                     <p className="font-black text-indigo-600 uppercase tracking-widest text-xs">Gemini is thinking...</p>
                  </div>
               </div>
             )}

             <div className="flex-1 overflow-y-auto p-12 md:p-20 max-w-5xl mx-auto w-full font-student">
                <input 
                  type="text" 
                  value={activeNote.title}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'title', e.target.value)}
                  placeholder="Note Title"
                  className="w-full text-6xl font-black text-gray-900 placeholder-gray-100 border-none focus:outline-none focus:ring-0 bg-transparent mb-12 selection:bg-indigo-100"
                />
                <textarea
                  value={activeNote.content}
                  onChange={(e) => handleUpdateNote(activeNote.id, 'content', e.target.value)}
                  placeholder="Start your collaboration journey here..."
                  className="w-full h-full min-h-[600px] resize-none text-gray-700 text-2xl leading-relaxed border-none focus:outline-none focus:ring-0 bg-transparent selection:bg-indigo-100 whitespace-pre-wrap"
                />
             </div>
           </>
         ) : (
           <div className="flex-1 flex flex-col items-center justify-center text-gray-200 no-print">
             <div className="w-40 h-40 bg-gray-50 rounded-[3rem] flex items-center justify-center mb-8">
                <BookOpen className="w-20 h-20 opacity-5" />
             </div>
             <p className="text-2xl font-black text-gray-400">Collaborate & Create</p>
             <p className="text-sm font-bold text-gray-300">Select a note to begin the development process.</p>
           </div>
         )}
      </div>
    </div>
  );
};

export default MyNotes;

