import React, { useState, useRef, useEffect } from 'react';
import { Search, Bell, ChevronDown, Menu, Sparkles, X } from 'lucide-react';
import { NOTIFICATIONS } from '../constants';

interface HeaderProps {
  toggleSidebar: () => void;
  onNavigate: (page: string) => void;
}

const Header: React.FC<HeaderProps> = ({ toggleSidebar, onNavigate }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const unreadCount = NOTIFICATIONS.filter(n => !n.read).length;

  return (
    <header className="sticky top-0 z-50 bg-white/90 backdrop-blur-xl border-b border-gray-100 px-4 py-3 flex items-center justify-between gap-4 animate-fade-up">

      {/* Search Overlay for Mobile */}
      {isSearchOpen && (
        <div className="absolute inset-0 bg-white z-50 flex items-center px-4 animate-fade-up lg:hidden">
          <div className="relative flex-1 group">
            <span className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none">
              <Search className="h-5 w-5 text-indigo-500" />
            </span>
            <input
              type="text"
              autoFocus
              className="w-full py-3 pl-12 pr-12 bg-gray-50 border-2 border-indigo-100 rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-50 transition-all font-medium text-sm"
              placeholder="Search everything..."
            />
            <button 
              onClick={() => setIsSearchOpen(false)}
              className="absolute inset-y-0 right-0 flex items-center pr-4 text-gray-400 hover:text-gray-600"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
      )}

      <div className="flex items-center space-x-2 sm:space-x-4 min-w-fit">
        <button 
          onClick={toggleSidebar} 
          className="p-2 hover:bg-gray-100 rounded-xl transition-colors text-gray-600"
        >
          <Menu className="h-6 w-6" />
        </button>

        <div 
          className="flex items-center space-x-2 cursor-pointer group"
          onClick={() => onNavigate('Home')}
        >
          <div className="w-8 h-8 sm:w-10 sm:h-10 bg-indigo-600 rounded-[0.8rem] flex items-center justify-center text-white shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
             <Sparkles className="w-5 h-5 sm:w-6 sm:h-6" />
          </div>
          <span className="text-xl sm:text-2xl font-black text-gray-800 hidden sm:block tracking-tight">StudyBuddy</span>
        </div>
      </div>

      <div className="flex-1 max-w-xl px-4 hidden lg:block">
        <div className="relative group">
          <span className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none">
            <Search className="h-5 w-5 text-gray-300 group-focus-within:text-indigo-500 transition-colors" />
          </span>
          <input
            type="text"
            className="w-full py-2.5 pl-12 pr-4 bg-gray-50 border border-transparent focus:bg-white focus:border-indigo-100 rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-50 transition-all duration-300 font-medium text-sm"
            placeholder="Search notes, flashcards..."
          />
        </div>
      </div>

      <div className="flex items-center space-x-2 sm:space-x-4 min-w-fit justify-end relative">
        <button 
          onClick={() => setIsSearchOpen(true)}
          className="lg:hidden p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-xl transition-colors"
        >
          <Search className="h-5 w-5" />
        </button>

        <div className="relative" ref={notifRef}>
          <button 
            onClick={() => setShowNotifications(!showNotifications)}
            className={`p-2.5 rounded-xl transition-colors relative ${showNotifications ? 'bg-indigo-50 text-indigo-600' : 'bg-gray-50 hover:bg-gray-100 text-gray-600'}`}
          >
            <Bell className="h-5 w-5" />
            {unreadCount > 0 && (
              <span className="absolute top-1 right-1.5 block h-2.5 w-2.5 rounded-full bg-red-500 ring-4 ring-white"></span>
            )}
          </button>

          {showNotifications && (
            <div className="absolute right-0 mt-3 w-72 sm:w-80 bg-white rounded-[2rem] shadow-2xl border border-gray-100 overflow-hidden animate-fade-up origin-top-right">
              <div className="p-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-black text-gray-800 text-sm sm:text-base">Alerts</h3>
                <span className="text-[10px] font-black uppercase text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{unreadCount} New</span>
              </div>
              <div className="max-h-[300px] sm:max-h-[350px] overflow-y-auto">
                {NOTIFICATIONS.map(notif => (
                   <div key={notif.id} className="p-4 sm:p-5 border-b border-gray-50 hover:bg-indigo-50/30 transition-colors cursor-pointer" onClick={() => {onNavigate('Notifications'); setShowNotifications(false);}}>
                      <div className="flex justify-between items-start mb-1">
                        <span className={`text-xs sm:text-sm font-bold ${!notif.read ? 'text-gray-900' : 'text-gray-500'}`}>{notif.title}</span>
                        <span className="text-[9px] font-bold text-gray-400">{notif.time}</span>
                      </div>
                      <p className="text-[10px] sm:text-xs text-gray-500 line-clamp-2 leading-relaxed">{notif.message}</p>
                   </div>
                ))}
              </div>
              <div className="p-4 bg-gray-50 text-center">
                <button onClick={() => {onNavigate('Notifications'); setShowNotifications(false);}} className="text-[10px] sm:text-xs font-black text-indigo-600 hover:underline">View All Notifications</button>
              </div>
            </div>
          )}
        </div>

        <div 
          onClick={() => onNavigate('Profile')}
          className="flex items-center space-x-2 sm:space-x-3 cursor-pointer p-1 rounded-2xl hover:bg-gray-50 transition-colors"
        >
          <img
            className="h-9 w-9 sm:h-10 sm:w-10 rounded-xl border-2 border-white shadow-sm"
            src="https://ui-avatars.com/api/?name=Vivek+Pawar&background=4F46E5&color=fff"
            alt="Vivek"
          />
          <div className="hidden sm:block text-left">
            <p className="text-xs sm:text-sm font-black text-gray-800 leading-none">Vivek Pawar</p>
            <p className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Active</p>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

